--
-- Table structure for table `decision_formulas`
--

DROP TABLE IF EXISTS `decision_formulas`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `decision_formulas` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `crop_type` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `season` enum('wet','dry') COLLATE utf8mb4_unicode_ci NOT NULL,
  `stage` varchar(30) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'standard',
  `product_id` bigint(20) unsigned NOT NULL,
  `rate_per_hectare` decimal(8,2) NOT NULL,
  `min_rate_per_hectare` decimal(8,2) DEFAULT NULL,
  `max_rate_per_hectare` decimal(8,2) DEFAULT NULL,
  `unit` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `crop_season_product_stage_unique` (`crop_type`,`season`,`product_id`,`stage`),
  KEY `decision_formulas_product_id_foreign` (`product_id`),
  CONSTRAINT `decision_formulas_product_id_foreign` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=521 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

