CREATE TABLE `farmer_crops` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `user_id` bigint(20) unsigned NOT NULL,
  `crop_id` bigint(20) unsigned NOT NULL,
  `variety` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Variety display name chosen in the New Crop Batch form',
  `variety_key` varchar(60) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Stable library key; "general" for Local / General variety',
  `product_id` bigint(20) unsigned DEFAULT NULL,
  `harvest_report_id` bigint(20) unsigned DEFAULT NULL,
  `batch_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `land_area` decimal(8,2) NOT NULL DEFAULT 1.00,
  `land_area_unit` varchar(10) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'ha',
  `planting_date` date NOT NULL,
  `expected_harvest_date` date DEFAULT NULL,
  `actual_harvest_date` date DEFAULT NULL,
  `growth_stage` enum('land_prep','seeding','vegetative','reproductive','ripening','harvested','failed') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'seeding',
  `season` enum('wet','dry') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'wet',
  `confirmation_status` enum('pending','confirmed','rejected') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'pending',
  `confirmed_by` bigint(20) unsigned DEFAULT NULL,
  `confirmed_at` timestamp NULL DEFAULT NULL,
  `admin_remarks` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `estimated_yield` decimal(10,2) DEFAULT NULL,
  `yield_unit` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `actual_yield` decimal(10,2) DEFAULT NULL,
  `estimated_cost` decimal(12,2) DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `farmer_crops_user_id_foreign` (`user_id`),
  KEY `farmer_crops_crop_id_foreign` (`crop_id`),
  KEY `farmer_crops_product_id_foreign` (`product_id`),
  KEY `farmer_crops_harvest_report_id_foreign` (`harvest_report_id`),
  KEY `farmer_crops_confirmed_by_foreign` (`confirmed_by`),
  CONSTRAINT `farmer_crops_confirmed_by_foreign` FOREIGN KEY (`confirmed_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `farmer_crops_crop_id_foreign` FOREIGN KEY (`crop_id`) REFERENCES `crops` (`id`) ON DELETE CASCADE,
  CONSTRAINT `farmer_crops_harvest_report_id_foreign` FOREIGN KEY (`harvest_report_id`) REFERENCES `harvest_reports` (`id`) ON DELETE SET NULL,
  CONSTRAINT `farmer_crops_product_id_foreign` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE SET NULL,
  CONSTRAINT `farmer_crops_user_id_foreign` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=155 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
