INSERT INTO `products` VALUES (126,55,'OKR-UREA-46-50','Fertilizer','Urea Fertilizer (46-0-0)','Atlas','Fertilizer',2150.00,'per sack',120,0,'sacks',120,25,'both','active',NULL,'High-nitrogen granular fertilizer (46% N) for rapid vegetative growth. Best applied during tillering and panicle initiation of rice and corn.',50.00,'kg',NULL,'2026-09-20 20:01:48','2026-10-06 10:29:03',3),(127,55,'OKR-COMP-141414-50','Fertilizer','Complete Fertilizer (14-14-14)','Atlas','Fertilizer',1780.00,'per sack',95,0,'sacks',95,20,'both','active',NULL,'Balanced NPK compound for basal application. Supports root development, tillering, and grain filling across rice, corn, and vegetables.',50.00,'kg',NULL,'2026-09-20 20:01:49','2026-10-16 02:59:44',2),(128,50,'GAC-AMS-2100-50','Fertilizer','Ammonium Sulfate (21-0-0)','Philphos','Fertilizer',1480.00,'per sack',60,0,'sacks',60,12,'both','active',NULL,'Nitrogen fertilizer with sulfur. Ideal for top-dressing and for acidifying soils around onion and high-value crops.',50.00,'kg','Sack','2026-09-20 20:01:49','2026-09-30 04:57:11',3),(129,55,'OKR-MOP-0060-50','Fertilizer','Muriate of Potash (0-0-60)','Atlas','Fertilizer',1650.00,'per sack',55,0,'sacks',55,12,'both','active',NULL,'High-potassium fertilizer. Strengthens stems, improves disease resistance, and enhances grain and fruit quality.',50.00,'kg',NULL,'2026-09-20 20:01:49','2026-10-16 06:10:53',5),(130,55,'OKR-NPK-16200-50','Fertilizer','NPK Fertilizer (16-20-0)','Philphos','Fertilizer',1950.00,'per sack',70,0,'sacks',70,15,'both','active',NULL,'Phosphorus-rich NPK ideal for root establishment and early flowering of rice, corn, banana, and vegetables.',50.00,'kg',NULL,'2026-09-20 20:01:49','2026-10-16 06:15:27',2),(131,50,'GAC-SUPERPHOS-00200-50','Fertilizer','Superphosphate (0-20-0)','Philphos','Fertilizer',1250.00,'per sack',40,1,'sacks',40,10,'both','active',NULL,'Phosphorus-only fertilizer for legumes, root crops, and fruit set. Works best incorporated before planting.',50.00,'kg','Sack','2026-09-20 20:01:49','2026-10-07 08:12:49',2),(132,55,'OKR-MICRO-ZNSULF-1','Micronutrient','Zinc Sulfate Micronutrient (33% Zn)','Agri-Cool','Fertilizer',120.00,'per pack',120,0,'packs',120,15,'both','active',NULL,'Prevents zinc deficiency in lowland rice and corn, especially on alkaline soils. Mix into soil or foliar spray.',1.00,'kg','Pack','2026-09-20 20:01:49','2026-09-30 04:57:11',5),(133,55,'OKR-FOL-GROMORE-1','Micronutrient','Foliar Fertilizer Grow More (14-40-13)','Grow More','Fertilizer',180.00,'per pack',200,3,'packs',200,20,'both','active',NULL,'Water-soluble foliar fertilizer for flowering and fruit set. Boom sprayer or knapsack application on vegetables, rice, and corn.',1.00,'kg',NULL,'2026-09-20 20:01:49','2026-10-07 08:13:02',5),(134,50,'GAC-ORG-VERMICAST-25','Organic Fertilizer','Vermicast Organic Fertilizer','VermiGrow','Fertilizer',260.00,'per sack',200,1,'sacks',200,25,'both','active',NULL,'Premium vermicompost rich in NPK and beneficial microbes. Improves soil structure and water retention. Safe for organic farming.',25.00,'kg','Sack','2026-09-20 20:01:49','2026-10-07 08:13:00',4),(135,50,'GAC-ORG-SUPERHUMUS-25','Organic Fertilizer','Super Humus Organic Fertilizer','Superhumus','Fertilizer',450.00,'per sack',120,0,'sacks',120,20,'both','active',NULL,'Decomposed organic matter enriched with humic and fulvic acids. Ideal soil conditioner for rice, corn, and vegetables.',25.00,'kg','Sack','2026-09-20 20:01:49','2026-09-30 04:57:11',4),(136,50,'GAC-ORG-BION-500','Organic Fertilizer','Bio-N Nitrogen Biofertilizer','BIOTECH','Fertilizer',150.00,'per bottle',150,0,'bottles',150,15,'both','active',NULL,'Biofertilizer packed with nitrogen-fixing bacteria. Reduces urea requirement by 30ΓÇô50% when coated onto seeds before planting.',500.00,'mL','Bottle','2026-09-20 20:01:50','2026-09-30 04:57:11',4),(137,50,'GAC-SOIL-LIME-25','Soil Amendment','Agricultural Lime (Calcium Carbonate)','Agri-Lime','Soil Amendments',320.00,'per sack',80,1,'sacks',80,15,'both','active',NULL,'Raises soil pH in acidic (peat/organic) fields, improves nutrient availability, and supplies calcium for better tillering.',25.00,'kg','Sack','2026-09-20 20:01:50','2026-10-07 08:12:52',19),(138,55,'OKR-SEED-RC222-25','Seeds','NSIC Rc222 Rice Seeds','PhilRice','Seeds and Planting Materials',1450.00,'per sack',85,0,'sacks',85,15,'wet','active',NULL,'Flood-tolerant certified rice seed ideal for wet season lowland planting. Maturity: 120ΓÇô125 days. Potential yield: 4.5ΓÇô5.5 tons/ha.',25.00,'kg',NULL,'2026-09-20 20:01:50','2026-10-06 17:08:19',7),(139,55,'OKR-SEED-RC216-25','Seeds','NSIC Rc216 Rice Seeds','PhilRice','Seeds and Planting Materials',1650.00,'per sack',60,1,'sacks',60,15,'dry','active',NULL,'High-yielding inbred rice for dry season irrigated conditions. Maturity: 115ΓÇô120 days. Potential yield: 5.0ΓÇô6.0 tons/ha. Excellent grain quality.',25.00,'kg',NULL,'2026-09-20 20:01:50','2026-10-07 08:12:50',7),(140,55,'OKR-SEED-RC302-25','Seeds','NSIC Rc302 (Submarino) Rice Seeds','PhilRice','Seeds and Planting Materials',1550.00,'per sack',50,0,'sacks',50,12,'wet','active',NULL,'Submerge-tolerant rice variety for flood-prone lowland fields. Recovers after 14 days submerged. Maturity: 115ΓÇô120 days.',25.00,'kg',NULL,'2026-09-20 20:01:50','2026-10-07 03:23:34',7),(141,52,'AQD-SEED-CORNNK-20','Seeds','NK 8828 Hybrid Corn Seeds','Syngenta','Seeds and Planting Materials',2950.00,'per sack',40,1,'sacks',40,10,'both','active',NULL,'Premium hybrid corn for grain production. Excellent standability and uniform ear loading. Potential yield: 8ΓÇô10 tons/ha.',20.00,'kg','Sack','2026-09-20 20:01:50','2026-10-07 08:12:26',8),(142,52,'AQD-SEED-SWEETCORN-1','Seeds','Aelah Sweet Corn Seeds','Syngenta','Seeds and Planting Materials',1250.00,'per pack',55,0,'packs',55,12,'both','active',NULL,'Sweet corn variety prized for fresh market. High sugar content, tender kernels. Maturity: 75ΓÇô80 days. Suitable for direct seeding.',1.00,'kg','Pack','2026-09-20 20:01:50